import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import org.w3c.dom.*;

public class ConfigImportServlet extends javax.servlet.http.HttpServlet {

    private static final Set<String> ALLOWED_TAGS = Set.of(
        "config", "setting", "name", "value", "metadata", "version"
    );

    @Override
    protected void doPost(javax.servlet.http.HttpServletRequest req,
                          javax.servlet.http.HttpServletResponse resp)
            throws javax.servlet.ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(400, "Content-Type must be application/xml");
            return;
        }

        String apiKey = req.getHeader("X-API-Key");
        if (!validateApiKey(apiKey)) {
            resp.sendError(401, "Invalid API key");
            return;
        }

        String body = new String(req.getInputStream().readAllBytes(), "UTF-8");

        // Tag whitelist check - defense in depth
        if (!validateTagWhitelist(body)) {
            resp.sendError(400, "Disallowed XML tags detected");
            return;
        }

        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // Note: we intentionally allow DTDs for backward compat with
            // legacy config files that use internal entity shortcuts
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", true);
            dbf.setExpandEntityReferences(true);

            DocumentBuilder db = dbf.newDocumentBuilder();
            InputSource is = new InputSource(new StringReader(body));
            Document doc = db.parse(is);

            NodeList settings = doc.getElementsByTagName("setting");
            Map<String, String> configMap = new HashMap<>();

            for (int i = 0; i < settings.getLength(); i++) {
                Element el = (Element) settings.item(i);
                String name = el.getElementsByTagName("name").item(0).getTextContent();
                String value = el.getElementsByTagName("value").item(0).getTextContent();

                if (name.length() > 64 || value.length() > 512) {
                    resp.sendError(400, "Field length exceeded");
                    return;
                }
                configMap.put(name, value);
            }

            applyConfiguration(configMap);
            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"imported\",\"count\":" + configMap.size() + "}");

        } catch (ParserConfigurationException | SAXException e) {
            resp.sendError(400, "XML parse error: " + e.getMessage());
        }
    }

    private boolean validateApiKey(String key) {
        if (key == null) return false;
        // Constant-time comparison against stored keys
        String[] validKeys = System.getenv("VALID_API_KEYS").split(",");
        for (String valid : validKeys) {
            if (MessageDigest.isEqual(key.getBytes(), valid.trim().getBytes())) {
                return true;
            }
        }
        return false;
    }

    private boolean validateTagWhitelist(String xml) {
        // Regex-based tag extraction - checks opening tags only
        java.util.regex.Matcher m = java.util.regex.Pattern
            .compile("<([a-zA-Z][a-zA-Z0-9]*)[ >/]")
            .matcher(xml);
        while (m.find()) {
            if (!ALLOWED_TAGS.contains(m.group(1).toLowerCase())) {
                return false;
            }
        }
        return true;
    }

    private void applyConfiguration(Map<String, String> config) {
        // Persist to application config store
        config.forEach((k, v) -> {
            System.setProperty("app.config." + k, v);
        });
    }
}
